const data = $input.first().json;

if (data.status !== 'OK') {
  throw new Error(`Google Maps Error: ${data.status} - ${data.error_message || 'Check API keys'}`);
}

const routes = data.routes;

// Sort routes by duration_in_traffic
const sortedRoutes = [...routes].sort((a, b) => {
  const timeA = a.legs[0].duration_in_traffic ? a.legs[0].duration_in_traffic.value : a.legs[0].duration.value;
  const timeB = b.legs[0].duration_in_traffic ? b.legs[0].duration_in_traffic.value : b.legs[0].duration.value;
  return timeA - timeB;
});

const best = sortedRoutes[0];
const leg = best.legs[0];

const inTraffic = leg.duration_in_traffic ? leg.duration_in_traffic.text : leg.duration.text;
const normal = leg.duration.text;

// Calculate delay minutes
const trafficSecs = leg.duration_in_traffic ? leg.duration_in_traffic.value : leg.duration.value;
const normalSecs = leg.duration.value;
const delayMins = Math.round((trafficSecs - normalSecs) / 60);

let delayStatus = "🟢 Smooth sailing!";
if (delayMins > 5) delayStatus = "🟠 Minor delays.";
if (delayMins > 15) delayStatus = "🔴 Heavy traffic alert!";

return [{
  json: {
    message: `🚗 *Commute Update*\n\nRoute: ${best.summary}\nStatus: ${delayStatus}\n\nTraffic Time: *${inTraffic}* ⏱️\nNormal Time: ${normal}\nDelay: ${delayMins > 0 ? delayMins + " min" : "None"}\nDistance: ${leg.distance.text}`
  }
}];
